/// The result of applying an action to the PCG.
#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
#[cfg_attr(feature = "type-export", derive(ts_rs::TS))]
#[cfg_attr(feature = "type-export", ts(export))]
pub(crate) struct ApplyActionResult<Summary = DisplayOutput> {
    /// Whether the action had any effect on the PCG state.
    pub changed: bool,
    /// A summary of the changes made by the action.
    pub change_summary: Summary,
}

impl DebugRepr<()> for ApplyActionResult {
    type Repr = ApplyActionResult<String>;

    fn debug_repr(&self, _ctxt: ()) -> Self::Repr {
        ApplyActionResult {
            changed: self.changed,
            change_summary: self.change_summary.clone().into_html().to_string(),
        }
    }
}

impl ApplyActionResult {
    pub(crate) fn changed_no_display() -> Self {
        Self {
            changed: true,
            change_summary: DisplayOutput::EMPTY,
        }
    }

    pub(crate) fn from_changed(changed: bool) -> Self {
        Self {
            changed,
            change_summary: DisplayOutput::EMPTY,
        }
    }
}

impl<'tcx, EdgeKind, P> BorrowPcgAction<'tcx, EdgeKind, P> {
    pub(crate) fn add_edge(
        edge: BorrowPcgEdge<'tcx, EdgeKind>,
        context: impl Into<DisplayOutput>,
    ) -> Self {
        Self::add_edge_setting(edge, vec![], context)
    }

    pub(crate) fn add_edge_setting(
        edge: BorrowPcgEdge<'tcx, EdgeKind>,
        capabilities: Vec<(P, Option<CapabilityKind>)>,
        context: impl Into<DisplayOutput>,
    ) -> Self {
        BorrowPcgAction {
            kind: BorrowPcgActionKind::AddEdge { edge, capabilities },
            debug_info: Some(context.into()),
        }
    }

    pub(crate) fn remove_edge(
        edge: BorrowPcgEdge<'tcx, EdgeKind>,
        context: impl Into<DisplayOutput>,
    ) -> Self {
        Self::remove_edge_regaining(edge, vec![], context)
    }

    pub(crate) fn remove_edge_regaining(
        edge: BorrowPcgEdge<'tcx, EdgeKind>,
        regained: Vec<(P, CapabilityKind)>,
        context: impl Into<DisplayOutput>,
    ) -> Self {
        BorrowPcgAction {
            kind: BorrowPcgActionKind::RemoveEdge { edge, regained },
            debug_info: Some(context.into()),
        }
    }
}

impl<'tcx, P: PcgNodeComponent, VC> BorrowPcgAction<'tcx, BorrowPcgEdgeKind<'tcx, P>, P, VC> {
    pub(crate) fn weaken(
        place: P,
        from: CapabilityKind,
        to: Option<CapabilityKind>,
        context: impl Into<DisplayOutput>,
    ) -> Self {
        BorrowPcgAction::<'tcx, BorrowPcgEdgeKind<'tcx, P>, P, VC> {
            kind: BorrowPcgActionKind::<'tcx, BorrowPcgEdgeKind<'tcx, P>, P, VC>::Weaken(
                Weaken::new(place, from, to),
            ),
            debug_info: Some(context.into()),
        }
    }

    pub(crate) fn freeze(place: P, context: impl Into<DisplayOutput>) -> Self {
        BorrowPcgAction::<'tcx, BorrowPcgEdgeKind<'tcx, P>, P, VC> {
            kind: BorrowPcgActionKind::<'tcx, BorrowPcgEdgeKind<'tcx, P>, P, VC>::Freeze { place },
            debug_info: Some(context.into()),
        }
    }

    pub(crate) fn unfreeze(place: P, context: impl Into<DisplayOutput>) -> Self {
        BorrowPcgAction::<'tcx, BorrowPcgEdgeKind<'tcx, P>, P, VC> {
            kind: BorrowPcgActionKind::<'tcx, BorrowPcgEdgeKind<'tcx, P>, P, VC>::Unfreeze {
                place,
            },
            debug_info: Some(context.into()),
        }
    }

    pub(crate) fn refreeze(place: P, to: Vec<P>, context: impl Into<DisplayOutput>) -> Self {
        BorrowPcgAction::<'tcx, BorrowPcgEdgeKind<'tcx, P>, P, VC> {
            kind: BorrowPcgActionKind::<'tcx, BorrowPcgEdgeKind<'tcx, P>, P, VC>::Refreeze {
                place,
                to,
            },
            debug_info: Some(context.into()),
        }
    }

    pub(crate) fn activate_two_phase_borrow(
        borrow: BorrowEdge<'tcx, P>,
        context: impl Into<DisplayOutput>,
    ) -> Self {
        BorrowPcgAction::<'tcx, BorrowPcgEdgeKind<'tcx, P>, P, VC> {
            kind: BorrowPcgActionKind::<'tcx, BorrowPcgEdgeKind<'tcx, P>, P, VC>::ActivateTwoPhaseBorrow {
                borrow,
            },
            debug_info: Some(context.into()),
        }
    }

    pub(crate) fn remove_lifetime_projection_label(
        projection: LifetimeProjection<'tcx, MaybeLabelledPlace<'tcx, P>>,
        context: impl Into<DisplayOutput>,
    ) -> Self {
        BorrowPcgAction::<'tcx, BorrowPcgEdgeKind<'tcx, P>, P, VC> {
            kind: BorrowPcgActionKind::<'tcx, BorrowPcgEdgeKind<'tcx, P>, P, VC>::remove_lifetime_projection_label(projection),
            debug_info: Some(context.into()),
        }
    }

    pub(crate) fn label_lifetime_projection(
        predicate: LabelNodePredicate<'tcx, P>,
        label: Option<LifetimeProjectionLabel>,
        context: impl Into<DisplayOutput>,
    ) -> Self {
        BorrowPcgAction::<'tcx, BorrowPcgEdgeKind<'tcx, P>, P, VC> {
            kind: BorrowPcgActionKind::<'tcx, BorrowPcgEdgeKind<'tcx, P>, P, VC>::label_lifetime_projection(predicate, label),
            debug_info: Some(context.into()),
        }
    }

    pub(crate) fn label_place_and_update_related_capabilities(
        place: P,
        location: SnapshotLocation,
        reason: LabelPlaceReason,
    ) -> Self {
        BorrowPcgAction::<'tcx, BorrowPcgEdgeKind<'tcx, P>, P, VC> {
            kind: BorrowPcgActionKind::<'tcx, BorrowPcgEdgeKind<'tcx, P>, P, VC>::LabelPlace(
                LabelPlaceAction::new(place, location, reason),
            ),
            debug_info: None,
        }
    }
}

#[deprecated(note = "Use LabelPlaceReason instead")]
pub type MakePlaceOldReason = LabelPlaceReason;

#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub enum LabelPlaceReason {
    StorageDead,
    MoveOut,
    /// When joining an owned place where one place has capability Read and the
    /// other has capability Write, all borrowed expansions of the place with
    /// Read capability should be labelled.
    ///
    /// In particular, the Read capability place could be a shared reference that is dereferenced.
    /// The place will not have any capability after the join, but reborrows derived from the dereference
    /// may still have capability.
    JoinOwnedReadAndWriteCapabilities,
    Write,
    Collapse,
    /// Label lifetime projections of places that are mutated in a loop.
    JoinLoop,
}

impl LabelPlaceReason {
    pub(crate) fn apply_to_edge<'a, 'tcx: 'a, Ctxt: Copy, P: PcgPlace<'tcx, Ctxt>>(
        self,
        place: P,
        edge: &mut impl LabelEdgePlaces<'tcx, Ctxt, P>,
        labeller: &impl PlaceLabeller<'tcx, Ctxt, P>,
        ctxt: Ctxt,
    ) -> HashSet<NodeReplacement<'tcx, P>> {
        let predicate: LabelNodePredicate<'tcx, P> = match self {
            LabelPlaceReason::JoinLoop => LabelNodePredicate::And(vec![
                LabelNodePredicate::PlaceIsPostfixOf(place),
                LabelNodePredicate::NodeType(PcgNodeType::LifetimeProjection),
            ]),
            LabelPlaceReason::StorageDead
            | LabelPlaceReason::MoveOut
            | LabelPlaceReason::JoinOwnedReadAndWriteCapabilities => {
                LabelNodePredicate::PlaceIsPostfixOf(place)
            }
            LabelPlaceReason::Write => LabelNodePredicate::And(vec![
                LabelNodePredicate::PlaceIsPostfixOf(place),
                // If the place is e.g *x or x.f, don't label it if it
                // is the target of a borrow expansion or deref edge.
                LabelNodePredicate::not(LabelNodePredicate::And(vec![
                    LabelNodePredicate::PlaceEquals(place),
                    LabelNodePredicate::InTargetNodes,
                    LabelNodePredicate::NodeType(PcgNodeType::Place),
                    LabelNodePredicate::Or(vec![
                        LabelNodePredicate::EdgeType(BorrowPcgEdgeType::BorrowPcgExpansion),
                        LabelNodePredicate::EdgeType(BorrowPcgEdgeType::Deref),
                    ]),
                ])),
                // If we are writing to e.g. x.f and there's an
                // edge "x.f|'a -> x|'a  at FUTURE", we DON'T want to label the source:
                // the stuff that will reside in x'|a will be determined by the new contents of x.f|'a
                // We don't want an edge like "x.f at bb2[6] |'a -> x|'a at FUTURE"
                LabelNodePredicate::not(LabelNodePredicate::And(vec![
                    LabelNodePredicate::PlaceEquals(place),
                    LabelNodePredicate::InSourceNodes,
                    LabelNodePredicate::EdgeType(BorrowPcgEdgeType::BorrowFlow {
                        future_edge_kind: Some(FutureEdgeKind::FromExpansion),
                    }),
                ])),
            ]),
            LabelPlaceReason::Collapse => LabelNodePredicate::PlaceEquals(place),
        };
        let mut result = edge.label_blocked_by_places(&predicate, labeller, ctxt);
        result.extend(edge.label_blocked_places(&predicate, labeller, ctxt));
        result
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct LabelPlaceAction<'tcx, P = Place<'tcx>> {
    pub(crate) place: P,
    pub(crate) location: SnapshotLocation,
    pub(crate) reason: LabelPlaceReason,
    /// The capabilities set once the old value is labelled: the owned leaves
    /// of a place labelled for a write that are no longer blocked get W.
    pub(crate) capabilities: Vec<(P, CapabilityKind)>,
    _marker: PhantomData<&'tcx ()>,
}

impl<P> LabelPlaceAction<'_, P> {
    pub(crate) fn new(place: P, location: SnapshotLocation, reason: LabelPlaceReason) -> Self {
        Self {
            place,
            location,
            reason,
            capabilities: vec![],
            _marker: PhantomData,
        }
    }
}

impl<'a, 'tcx: 'a, Ctxt: HasBorrowCheckerCtxt<'a, 'tcx>> DisplayWithCtxt<Ctxt>
    for LabelPlaceAction<'tcx>
{
    fn display_output(&self, ctxt: Ctxt, _mode: OutputMode) -> DisplayOutput {
        let mut text = format!(
            "Label place {} ({:?})",
            self.place.display_string(ctxt),
            self.reason
        );
        if !self.capabilities.is_empty() {
            text.push_str(" setting ");
            text.push_str(
                &self
                    .capabilities
                    .iter()
                    .map(|(place, cap)| format!("{}: {cap:?}", place.display_string(ctxt)))
                    .collect::<Vec<_>>()
                    .join(", "),
            );
        }
        DisplayOutput::Text(text.into())
    }
}

mod private {
    use crate::{
        borrow_pcg::{
            edge_data::LabelNodePredicate,
            region_projection::{LifetimeProjection, LifetimeProjectionLabel},
        },
        pcg::PcgNode,
        utils::{
            HasBorrowCheckerCtxt, Place,
            display::{DisplayOutput, DisplayWithCtxt, OutputMode},
            maybe_old::MaybeLabelledPlace,
        },
    };

    #[derive(Clone, Debug, PartialEq, Eq)]
    pub struct LabelLifetimeProjectionAction<'tcx, P = Place<'tcx>> {
        predicate: LabelNodePredicate<'tcx, P>,
        label: Option<LifetimeProjectionLabel>,
    }

    impl<'tcx, P: Copy> LabelLifetimeProjectionAction<'tcx, P> {
        pub(crate) fn predicate(&self) -> &LabelNodePredicate<'tcx, P> {
            &self.predicate
        }

        pub(crate) fn label(&self) -> Option<LifetimeProjectionLabel> {
            self.label
        }

        pub(crate) fn new(
            predicate: LabelNodePredicate<'tcx, P>,
            label: Option<LifetimeProjectionLabel>,
        ) -> Self {
            Self { predicate, label }
        }

        pub(crate) fn remove_label(
            projection: LifetimeProjection<'tcx, MaybeLabelledPlace<'tcx, P>>,
        ) -> Self {
            Self {
                predicate: LabelNodePredicate::Equals(PcgNode::LifetimeProjection(
                    projection.rebase(),
                )),
                label: None,
            }
        }
    }

    impl<'a, 'tcx: 'a, Ctxt: HasBorrowCheckerCtxt<'a, 'tcx>> DisplayWithCtxt<Ctxt>
        for LabelLifetimeProjectionAction<'tcx>
    {
        fn display_output(&self, ctxt: Ctxt, mode: OutputMode) -> DisplayOutput {
            let predicate_label = self.predicate.display_output(ctxt, mode);
            if let Some(label) = self.label {
                DisplayOutput::Seq(vec![
                    "Label lifetime projection ".into(),
                    predicate_label,
                    " with label ".into(),
                    label.display_output((), mode),
                ])
            } else {
                DisplayOutput::Seq(vec![
                    "Unlabel lifetime projection ".into(),
                    self.predicate.display_output(ctxt, mode),
                ])
            }
        }
    }
}
use private::LabelLifetimeProjectionAction;

#[derive(Clone, Debug, PartialEq, Eq, strum_macros::EnumDiscriminants)]
#[strum_discriminants(derive(Serialize))]
#[cfg_attr(
    feature = "type-export",
    strum_discriminants(derive(ts_rs::TS), ts(export))
)]
#[cfg_attr(feature = "type-export", derive(ts_rs::TS))]
#[cfg_attr(
    feature = "type-export",
    ts(
        as = "BorrowPcgActionKindDebugRepr",
        bound = "EdgeKind: ts_rs::TS, P: ts_rs::TS, VC: ts_rs::TS",
        concrete(EdgeKind = String, P = String, VC = String)
    )
)]
pub enum BorrowPcgActionKind<
    'tcx,
    EdgeKind = BorrowPcgEdgeKind<'tcx>,
    P = Place<'tcx>,
    VC = ValidityConditions,
> {
    LabelLifetimeProjection(LabelLifetimeProjectionAction<'tcx, P>),
    Weaken(Weaken<'tcx, P>),
    /// The place goes from E to R because it is read or borrowed for read.
    /// Unlike a [`Weaken`], the E capability is only suspended: it comes back
    /// through [`BorrowPcgActionKind::Unfreeze`] or
    /// [`BorrowPcgActionKind::Refreeze`] of the same place, or is lent by
    /// [`BorrowPcgActionKind::ActivateTwoPhaseBorrow`].
    ///
    /// If the place is unpacked, it has no capability and its descendants
    /// hold the E or are frozen; they all become read copies under the
    /// frozen place.
    ///
    /// A place with R whose parent has R is a read copy of a frozen
    /// ancestor, not frozen itself.
    Freeze {
        place: P,
    },
    /// The place goes from R back to the E suspended by
    /// [`BorrowPcgActionKind::Freeze`], because no borrow of it is left. If
    /// the place is unpacked, the read unpacking becomes an exclusive one (as
    /// for [`BorrowPcgActionKind::Refreeze`] with no `to`).
    Unfreeze {
        place: P,
    },
    /// The freeze of the unpacked `place` ends while its descendants `to` are
    /// still borrowed: the freeze moves to `to`, which become frozen, and the
    /// rest of the unpacking of `place` gets its E back. The unpacking becomes
    /// an exclusive one: `place` and the places between it and `to` keep no
    /// capability (`e` for a mutable reference), and the other read copies
    /// get E (R if they are behind a shared reference).
    Refreeze {
        place: P,
        to: Vec<P>,
    },
    /// The two-phase borrow is activated: its blocked place goes from R to
    /// lent, i.e. the E suspended by the reservation's
    /// [`BorrowPcgActionKind::Freeze`] is lent to the borrow.
    ActivateTwoPhaseBorrow {
        borrow: BorrowEdge<'tcx, P>,
    },
    LabelPlace(LabelPlaceAction<'tcx, P>),
    /// Remove an edge from the PCG. In terms of the PCG itself, the validity
    /// conditions associated with the edge are not relevant (there is no
    /// situation where an edge is removed only under certain conditions).
    /// However, clients may be interested in the conditions, for example, the
    /// symbolic-execution based Prusti purification already performs some
    /// filtering on edges based on validity conditions and might want to ignore
    /// removal actions for edges that it already ignored.
    ///
    /// The places in `regained` were blocked only by the edge and get these
    /// capabilities back: the edge was an unpacking (its children's
    /// capability moves back to its base) or a loan (the lent capability
    /// returns).
    RemoveEdge {
        edge: BorrowPcgEdge<'tcx, EdgeKind, VC>,
        regained: Vec<(P, CapabilityKind)>,
    },
    /// Add an edge to the PCG. `capabilities` are the capabilities the edge
    /// sets (`None` removes one): an unpacking (a borrow-PCG expansion or a
    /// dereference) moves the capability of its base to its expansion, and a
    /// mutable borrow takes the capability of the borrowed place.
    AddEdge {
        edge: BorrowPcgEdge<'tcx, EdgeKind, VC>,
        capabilities: Vec<(P, Option<CapabilityKind>)>,
    },
}

impl<'tcx, P: PcgNodeComponent, VC> BorrowPcgActionKind<'tcx, BorrowPcgEdgeKind<'tcx, P>, P, VC> {
    pub(crate) fn remove_lifetime_projection_label(
        projection: LifetimeProjection<'tcx, MaybeLabelledPlace<'tcx, P>>,
    ) -> Self {
        Self::LabelLifetimeProjection(LabelLifetimeProjectionAction::remove_label(projection))
    }

    pub(crate) fn label_lifetime_projection(
        predicate: LabelNodePredicate<'tcx, P>,
        label: Option<LifetimeProjectionLabel>,
    ) -> Self {
        Self::LabelLifetimeProjection(LabelLifetimeProjectionAction::new(predicate, label))
    }
}

#[derive(Serialize)]
#[cfg_attr(feature = "type-export", derive(ts_rs::TS))]
#[cfg_attr(feature = "type-export", ts(export))]
pub(crate) struct BorrowPcgActionKindDebugRepr {
    r#type: BorrowPcgActionKindDiscriminants,
    data: String,
}

impl<'a, 'tcx: 'a, Ctxt: HasBorrowCheckerCtxt<'a, 'tcx>> DebugRepr<Ctxt>
    for BorrowPcgActionKind<'tcx>
{
    type Repr = BorrowPcgActionKindDebugRepr;

    fn debug_repr(&self, ctxt: Ctxt) -> Self::Repr {
        BorrowPcgActionKindDebugRepr {
            r#type: BorrowPcgActionKindDiscriminants::from(self),
            data: self.to_short_string(ctxt),
        }
    }
}

impl<'a, 'tcx: 'a, Ctxt: HasBorrowCheckerCtxt<'a, 'tcx>, EdgeKind: DisplayWithCtxt<Ctxt>>
    DisplayWithCtxt<Ctxt> for BorrowPcgActionKind<'tcx, EdgeKind>
{
    fn display_output(&self, ctxt: Ctxt, mode: OutputMode) -> DisplayOutput {
        match self {
            BorrowPcgActionKind::LabelLifetimeProjection(action) => {
                action.display_output(ctxt, mode)
            }
            BorrowPcgActionKind::Weaken(weaken) => weaken.display_output(ctxt, mode),
            BorrowPcgActionKind::Freeze { place } => DisplayOutput::join(
                vec!["Freeze".into(), place.display_output(ctxt, mode)],
                &DisplayOutput::SPACE,
            ),
            BorrowPcgActionKind::Unfreeze { place } => DisplayOutput::join(
                vec!["Unfreeze".into(), place.display_output(ctxt, mode)],
                &DisplayOutput::SPACE,
            ),
            BorrowPcgActionKind::Refreeze { place, to } => DisplayOutput::join(
                vec![
                    "Refreeze".into(),
                    place.display_output(ctxt, mode),
                    "to".into(),
                    DisplayOutput::join(
                        to.iter().map(|p| p.display_output(ctxt, mode)),
                        &", ".into(),
                    ),
                ],
                &DisplayOutput::SPACE,
            ),
            BorrowPcgActionKind::ActivateTwoPhaseBorrow { borrow } => DisplayOutput::join(
                vec![
                    "Activate two-phase borrow".into(),
                    borrow.display_output(ctxt, mode),
                ],
                &DisplayOutput::SPACE,
            ),
            BorrowPcgActionKind::LabelPlace(action) => action.display_output(ctxt, mode),
            BorrowPcgActionKind::RemoveEdge { edge, regained } => {
                let mut words = vec!["Remove Edge".into(), edge.display_output(ctxt, mode)];
                if !regained.is_empty() {
                    words.push(DisplayOutput::join(
                        regained.iter().map(|(place, cap)| {
                            DisplayOutput::join(
                                vec![
                                    "returning".into(),
                                    cap.display_output(ctxt, mode),
                                    "to".into(),
                                    place.display_output(ctxt, mode),
                                ],
                                &DisplayOutput::SPACE,
                            )
                        }),
                        &", ".into(),
                    ));
                }
                DisplayOutput::join(words, &DisplayOutput::SPACE)
            }
            BorrowPcgActionKind::AddEdge { edge, capabilities } => {
                let mut words = vec!["Add Edge".into(), edge.display_output(ctxt, mode)];
                if !capabilities.is_empty() {
                    words.push("setting".into());
                    words.push(DisplayOutput::join(
                        capabilities.iter().map(|(place, cap)| {
                            DisplayOutput::Seq(vec![
                                place.display_output(ctxt, mode),
                                ": ".into(),
                                match cap {
                                    Some(cap) => cap.display_output(ctxt, mode),
                                    None => "None".into(),
                                },
                            ])
                        }),
                        &", ".into(),
                    ));
                }
                DisplayOutput::join(words, &DisplayOutput::SPACE)
            }
        }
    }
}
